"""Build the seasonal guides from dated official-source records. Standard library only."""
from pathlib import Path
from html import escape as e
import json,re
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'data/seasonal-events.json').read_text('utf8'))
S=D['sources'];HOST='https://fukuroi.enshu-lifehack.com';B='/life/play-out/'
C=B+'seasonal-events/';M=B+'fukuroi-matsuri/';F=B+'enshu-hanabi/';T=B+'enshu-sanzan-seasons/'
def a(label,url):return '<a href="'+e(url,quote=True)+'">'+e(label).replace('🎆','').replace('✨','')+'</a>'
def p(s):return '<p>'+s+'</p>'
def refs(keys):return '<p class="references">公式情報：'+' ／ '.join(a(S[k]['label'],S[k]['url']) for k in keys.split())+'</p>'
def sec(id,title,body):return '<section class="course" id="'+id+'"><h2>'+title+'</h2>'+body+'</section>'
def item(title,body,keys=''):return '<div class="trip-note"><h3>'+title+'</h3>'+(body if body.startswith('<p') else p(body))+(refs(keys) if keys else '')+'</div>'
def ul(items):return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def journey(s):return '<p class="journey">'+s+'</p>'
def table(head,rows):return '<div class="event-table"><table><thead><tr>'+''.join('<th scope="col">'+v+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+v+'</th>') if i==0 else '<td>'+v+'</td>' for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def menu():return '<nav class="event-nav" aria-label="祭りと季節のガイド">'+' ／ '.join(a(t,u) for t,u in [('季節のカレンダー',C),('袋井まつり',M),('遠州の花火',F),('遠州三山',T)])+'</nav>'
def page(path,title,intro,body):
 template=(R/'tools/guide/index.html').read_text('utf8');head=template[:template.index('<main')]
 head=re.sub(r'<title>.*?</title>','<title>'+e(title)+' | 袋井ライフハック</title>',head)
 head=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="'+e(intro,quote=True)+'">',head)
 head=head.replace(HOST+'/tools/guide/',HOST+path).replace('/assets/living-tools.css','/assets/outings.css').replace('</head>','<link rel="stylesheet" href="/assets/events.css"></head>')
 foot=template[template.index('<!-- PART:footer:START -->'):]
 toc='<nav class="choose" aria-label="このページの目次"><strong>このページでわかること</strong><ul>'+''.join('<li>'+a(title,'#'+id)+'</li>' for id,title in re.findall(r'<section class="course" id="([^"]+)"><h2>(.*?)</h2>',body))+'</ul></nav>'
 body=toc+body
 text=head+'<main class="outing events-guide"><div class="wrap"><nav aria-label="パンくず">'+a('ホーム','/')+' › '+a('遊び・外出',B)+'</nav><header class="outing-head"><p class="eyebrow"><span aria-hidden="true">🏮</span> 袋井の季節を、行き帰りまで楽しもう</p><h1>'+e(title)+'</h1><p class="lead">'+e(intro)+'</p><p class="dated">公式情報の確認日：2026年11月18日</p></header>'+menu()+body+sec('before-go','出発前に、当日の案内をもう一度',p('開催年・中止や変更・受付条件・帰りの交通を主催者の最新案内で確認してください。以下の行程は公表資料をもとにした編集部の提案です。所要時間は混雑や子どもの歩く速さで延びます。現地の実踏・設備の実査をした記録ではありません。')+p(a('子連れ・車なしのお出かけ',B+'family-outings/')+' ／ '+a('食べ歩き・買い物',B+'food-shopping/')+' ／ '+a('公共交通の使い方','/life/start-living/public-transit/')))+ '</div></main><script defer src="/assets/event-calendar.js"></script>'+foot
 dest=R/path.strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text.rstrip()+'\n','utf8',newline='\n')

def calendar():
 places={'city':'袋井のまちなか・花火','hatta':'法多山','kasui':'可睡齋','yusan':'油山寺','sanzan':'遠州三山'}
 access={'walk':'JR＋徒歩を軸に','bus':'路線バス＋徒歩（日中）','taxi':'配車を組み合わせる','mixed':'寺ごとに移動方法が違う'}
 html='<form id="event-filter" class="event-filter" hidden><label>月<select id="event-month"><option value="">すべての月</option>'+''.join('<option value="'+str(m)+'">'+str(m)+'月</option>' for m in range(1,13))+'</select></label><label>場所<select id="event-place"><option value="">すべての場所</option>'+''.join('<option value="'+k+'">'+v+'</option>' for k,v in places.items())+'</select></label><label>行き方<select id="event-access"><option value="">すべての行き方</option>'+''.join('<option value="'+k+'">'+v+'</option>' for k,v in access.items())+'</select></label><label class="past-toggle"><input id="event-past" type="checkbox" checked> 掲載期間を過ぎた記録も表示</label><button type="reset">条件を解除</button></form><p id="event-count" role="status">'+str(len(D['events']))+'件</p><p id="event-empty" hidden>条件に合う行事はありません。月・場所・行き方の条件を解除してください。</p><div class="event-list">'
 for r in D['events']:
  status='例年の目安・次回詳細は要確認' if r['kind']=='annual' else ('掲載期間終了・過去の記録' if r['end']<D['checked'] else '日程発表あり・変更情報を確認')
  html+='<article id="'+r['id']+'" class="event-card" data-event data-months="'+','.join(map(str,r['months']))+'" data-place="'+r['place']+'" data-access="'+r['access']+'" data-end="'+r['end']+'"><p class="event-state"'+(' data-dated-state' if r['end'] else '')+'>'+status+'</p><h3>'+a(r['title'],r['guide'])+'</h3><p class="event-period">'+e(r['period'])+'</p>'+p(e(r['text']))+'<p class="event-access">'+access[r['access']]+'</p>'+refs(r['source'])+'</article>'
 return html+'</div>'

page(C,'袋井の祭り・季節のお出かけ','袋井まつり、遠州の花火、遠州三山の花と灯り。日程が出ている行事と例年の目安を分け、子どもと行ける時間帯や車なしの帰路から選びます。',
 sec('now','まず、次のお出かけを選ぶ',
 item('直近の紅葉：法多山は2026年11月21日～12月6日','もみじまつりのうち、昼のマーケットと夜のライトアップは11月28・29日、12月5・6日。全期間毎日開かれるわけではありません。'+a('日別の催しと親子コースを見る',T+'#momiji'),'momiji')+
 item('花火の次回：2027年7月31日（土）開催予定','主催者の発表は開催日の案内です。2027年の席種・料金・販売開始日・交通規制は、掲載中の2026年版と分けて確認します。'+a('駅選びとチケット確認の順序',F),'nextfire')+
 item('袋井まつり：2026年の掲載期間は終了','10月9～11日の屋台運行・規制図は過去の記録として紹介。2027年の日程は今回確認した公式情報では未確認です。'+a('中心部と北地区を分けて計画する',M),'matsuri'))+
 sec('calendar','月・場所・行き方で探す',p('「例年」は次回の開催発表ではありません。過去の記録は年を付けて表示し、翌年の日程へ置き換えません。行き方の「路線バス」は日中の往復を組む目安です。夜の催しの帰りに使えるかは、別に確認が必要です。')+calendar())+
 sec('choose','家族の過ごし方から選ぶ',table(['こんな日には','選び方'],[
 ['小さな子と短時間','袋井まつりは昼の屋台を見て駅へ。三山は一日に一寺とし、法多山の昼のスタンプラリー、可睡齋の花やひな飾りを候補に。'],
 ['路線バスで出かけたい','袋井駅北口1番から可睡齋入口へ。休日ダイヤと帰りの便を先に確認。法多山への旧路線バスは終了しているため、そのまま三山周遊には使えません。'],
 ['灯り・花火を見たい','花火は退場待ち・駅の乗車待ちを含めて帰路を計画。三山の夜間催事は帰りの配車を確保してから。日中の拝観時間と夜の行事時間は別です。'],
 ['雨・暑さで計画を変えたい','延期・中止は主催者の案内へ。雨の日の屋内施設は'+a('図書館・親子交流施設のガイド',B+'family-outings/#station')+'で開館日を確認。夜間の避難先や託児施設としては案内していません。']])+refs('kasuibus hattabus')))

page(M,'袋井まつりを子どもと楽しむ','駅から歩く袋井まつりと、北地区の祭りを区別。屋台の見方、昼の観覧、駅へ戻る道、バスの迂回までをまとめました。',
 sec('dates','2026年の記録と、次回の確認先',p('<strong>2026年10月9日（金）～11日（日）の掲載期間は終了しました。2027年の日程・屋台運行表・規制図は未確認です。</strong>月日だけを翌年の予定として使わないでください。')+p('袋井の秋祭りは、地域ごとに屋台や祢里を曳く祭礼です。観光協会は、北部には森町型、南部東側には横須賀型、南部西側には掛塚型が見られると紹介しています。各地区の祭りを、駅周辺と同じ時間・場所で見られるとは限りません。')+refs('matsuri matsuribase'))+
 sec('areas','中心部と北地区、見たい祭りを決める',
 item('袋井まつり：袋井駅北側～静橋周辺','駅から歩く計画の中心になるのはこちら。2026年の公式掲載ポスターには、10月9日13時から各町の曳き回し、10日12時の静橋15町渡橋、同日18時の静橋中心20町合同曳き回しが載っています。いずれも過去の運行記録で、翌年の待ち合わせ時刻には使えません。','matsuri')+
 item('ふくろい北祭り：袋井北地区の屋台','北祭りの公式サイトは、16車の屋台が北地区を巡る祭りとして案内しています。中心部の静橋周辺の催しとは別に、当年の運行図・集合場所を確認してください。駅北口に行けば北祭り全体が見られる、という案内ではありません。','kitanorth')+
 p('2026年10月11日20時の駅前「打上式」は屋台祭りの締めくくりの行事名です。打ち上げ花火の開催案内ではありません。')+refs('matsuri'))+
 sec('daytime','親子で歩く、昼の観覧プラン',journey('JR袋井駅北口 → 駅前で当年の規制図を確認 → 静橋周辺の観覧可能な場所へ → 休憩・食事 → 明るいうちに駅へ')+
 p('編集部の提案です。屋台の現在位置を固定時刻で追いかけず、当年の巡行表を見て一つの見どころに絞ると、幼児と戻りやすい計画になります。所要時間は、観覧と休憩を含めて家族で調整してください。')+
 ul(['曳き綱の中、屋台の前後や曲がり角へ入らず、係員の指示が届く位置で観覧。歩道や店舗の出入口も空けます。','ベビーカーで人垣を進む計画は避け、混み始めたら離れる場所と家族の集合場所を先に決めます。','屋台の通過時に道路を横断しない。子どもの写真を撮る間も、同伴者が手をつなげる配置にします。'])+
 item('昼の休憩・食事を組み合わせる',a('袋井駅周辺の親子交流施設・図書館',B+'family-outings/#station')+'は開館時間と休館日を確認。授乳やおむつ替えが必要なら、会場内の仮設設備の有無を当年の案内で確かめます。祭りの開催だけを理由に、公共施設が延長開館するとは限りません。'+a('駅からのたまごふわふわ・買い物',B+'food-shopping/#station')+'も営業時間と祭典日の臨時変更を確認して利用します。'))+
 sec('traffic','バス利用は「駅北口へ戻れるか」まで',p('2026年の観光協会掲載の交通規制図では、10月11日19時以降、袋井駅北口へのバス運行がなくなり、南口へ迂回する案内が出ていました。<strong>これは2026年の例です。次回の迂回日・時間・仮停留所を保証しません。</strong>')+
 p('往路で降りた停留所が、帰りも使えるとは限りません。夜の合同曳き回しを見る場合は、最後に観覧する場所から乗車口へ向かう道と、帰りの列車・バスを一組で決めてください。JRで帰る人も、規制区間を横切る近道を地図だけで選ばず、当日の誘導に従います。')+refs('matsuri buslive')+
 item('出発前に見る順序','観光協会の当年ポスター → 規制図と仮停留所 → 秋葉バスの運行変更 → 帰りの時刻表。駅の設備は'+a('JR東海・袋井駅のバリアフリー情報',S['railfuk']['url'])+'も確認できます。'))+
 sec('night','夜まで見るとき・雨の日',p('夜の屋台を見たい家族は、昼から連続して待ち続ける予定にせず、食事・トイレ・防寒・帰りの交通を先に確保します。子どもが音や混雑を嫌がるときは、最後まで見ずに離れる選択も。雨天時の曳き回しや日程変更は、当年の主催者発表を確認してください。')+p('問い合わせ先や最新発表は'+a('袋井市観光協会の秋の祭典案内',S['matsuri']['url'])+'と'+a('北祭り公式サイト',S['kitanorth']['url'])+'へ。期間限定の祭典本部の電話を、翌年も使える窓口として掲載していません。')))

page(F,'遠州の花火を子連れ・車なしで楽しむ','ふくろい遠州の花火2027は7月31日（土）開催予定。JRの駅選び、観覧席の確認、子どもの休憩、混雑する帰りまでを整理します。',
 sec('next','2027年は開催日を発表、詳細はこれから',p('<strong>ふくろい遠州の花火2027：2027年7月31日（土）開催予定。</strong>主催者の2026年9月9日発表では、協賛・チケットなどは決まり次第案内するとしています。今回、2027年の開催時刻・席種・価格・販売開始日・規制図は確認できていません。')+p('公式サイトには2026年の案内が残っています。以下で「2026年参考」とした席・退場・交通情報は、次回も同じ条件という意味ではありません。購入の判断には2027年版の発表を使ってください。')+refs('nextfire hanabinews'))+
 sec('rail','JRで行く：駅と出口を先に決める',journey('静岡方面から：JR愛野駅 → 徒歩で会場へ ／ 浜松方面から：JR袋井駅 → 徒歩で会場へ')+
 p('主催者の掲載中のアクセス案内は、会場を原野谷川親水公園（袋井市愛野3164-1）とし、両駅から徒歩約20分を目安にしています。これは混雑待ちや入場・席までの移動を含む到着保証ではありません。子どもとの歩行、トイレ、入場待ちの時間を加えてください。次回の推奨駅・動線は2027年の案内で再確認します。')+refs('traffic')+
 p('会場へ向かう前に飲料と必要な食事を準備。主催者FAQでは、近隣のコンビニや飲食店が少ないこと、有料エリア内の売店はチケットを持たない人が利用できないことを案内しています。食事を現地で必ず買える計画にしないようにします。')+refs('firefaq')+
 p('階段を避ける経路や駅設備は'+a('袋井駅',S['railfuk']['url'])+'・'+a('愛野駅',S['railaino']['url'])+'のJR東海公式情報へ。JRの臨時列車・最終列車は当年発表で確認し、2026年の増発や臨時きっぷを2027年も使えるものとして案内していません。'))+
 sec('seats','子どもの席は、人数と持ち物から確認',table(['2026年の参考条件','2027年に購入前に確かめること'],[
 ['ブロック席は3歳以上1人1枚のチケット','選ぶ席種の年齢条件を確認。小さな子の人数も含めて、家族全員が入場できる組合せを確認。'],
 ['ファミリーエリアは1区画4人まで、2.3m×1.7m','2027年の定員・広さ・敷物・幼児の扱い。家族という名称だけで人数無制限とは考えない。'],
 ['ファミリー・ブロック席は脚付きで高さのある椅子の使用不可','2026年FAQは座椅子・クッション等の利用を案内。2027年の椅子やベビーカーの扱い・通路へのはみ出し、クーラーボックスの制限を確認。'],
 ['椅子席・ブロック席など複数の席種','座り方、通路・トイレまでの距離、途中退場・再入場を照合。2026年の価格で予算を確定しない。']])+refs('venue firefaq')+
 item('授乳・おむつ替えは予約前に確認','今回読めた公式案内では、2027年の専用授乳室・おむつ替え台・ベビーカー預かりの有無は確認できていません。必要な設備と利用時間を主催者へ問い合わせてから観覧方法を選んでください。駅前施設が夜間も利用できるとは限りません。'))+
 sec('free','無料で見たい場合も、当年の観覧場所を確認',p('2026年FAQには、小野田河川公園や愛野公園などの観覧場所の案内がありますが、これを2027年の開放・眺望・場所取りの保証には使えません。開催年の会場図と禁止区域を見て選びます。公園の通常の駐車場情報と、花火当日の利用条件も別です。')+p('堤防道路・緊急車両の動線・住宅や農地に入って場所を取らず、当日の立入禁止や誘導を優先してください。有料席を買わない場合の売店・トイレ・休憩場所も、行く前に確認します。')+refs('firefaq traffic'))+
 sec('return','帰りは「徒歩20分」に退場待ちを足す',p('2026年は有料席のエリアごとに21時01分～21時30分の時間差退場が設定され、帰る方向に応じたゲートも指定されました。これは<strong>2026年の退場例</strong>で、2027年の終演時刻や帰着時刻ではありません。')+
 p('「終演から20分で駅、すぐ電車」という乗継は組まず、会場の退場待ち、駅までの混雑、改札・乗車待ちを含めて計画します。帰る駅と家族の集合場所を入場前に共有し、当日の場内放送・誘導員に従います。')+refs('fireexit traffic')+
 item('タクシーを会場前に呼べるとは限らない','観光協会の2026年FAQでは駅のタクシー利用を往路のみの案内とし、交通規制にも触れています。帰りに会場前で乗れる前提は置かず、配車会社と当年の乗降可能地点・時間を相談してください。','firefaqcity')+
 item('迷子・疲れたときの準備','主催者FAQでは迷子を本部・案内所・係員へ相談する案内があります。入場したら場所を確認し、連絡先を子どもの持ち物に入れる、充電を確保する、トイレに早めに行くなど家族の準備を。大きな音が苦手な子は無理をせず、休憩・途中退場の方法を係員に確認します。','firefaq'))+
 sec('plan','出発までにそろえるもの',ul([a('2027開催日の発表と続報',S['nextfire']['url'])+'：チケットの当年条件が出てから人数と席を決める。',a('交通アクセス・規制図',S['traffic']['url'])+'：2027年版かを確認。行きと帰りの駅、出口、乗継を一緒に選ぶ。',a('主催者のお知らせ',S['hanabinews']['url'])+'：雨天・変更・中止、持込制限、当日の運営案内を出発前に確認。'])+p('昼の食事やお土産は'+a('駅からの食べ歩き・買い物ガイド',B+'food-shopping/')+'へ。店舗の通常営業時間は花火当日の営業を保証しません。')))

page(T,'遠州三山の花と灯りを巡る','法多山・可睡齋・油山寺の紅葉、ひなまつり、桜、風鈴、夏と冬の行事。昼の親子散策と夜の催しを分け、行き帰りを組み立てます。',
 sec('momiji','法多山もみじまつり：2026年の日別ガイド',p('<strong>全体の期間は2026年11月21日（土）～12月6日（日）。催しごとに日が違います。</strong>夜のライトアップは毎日ではありません。下表は11月18日確認の公式発表です。変更時は法多山の新着を優先してください。')+
 table(['日・時間','楽しめること・条件'],[
 ['11月21日～12月6日 9～15時','境内のスタンプラリー。参加無料、台紙は境内各所・門前通り。散策と組み合わせやすい昼の催し。'],
 ['11月21～29日 10時から','厄除栗だんご券を数量限定販売。持ち帰り1箱800円、1人5箱まで。土日は参道テント、平日は売店前チケット売り場。12月の販売とは案内されていません。'],
 ['11月28・29日、12月5・6日 10～15時','マーケット・キッチンカー・ワークショップ。だんご茶屋前広場など境内各所。出店者は日によって変わります。'],
 ['同じ4日間 10～16時','持仏堂で豊臣秀吉の書状を特別公開。門前楽寮KADOYAのトヨトミカフェは10時30分～15時（LO14時30分）、予定数で終了。'],
 ['同じ4日間 17～21時','和傘アートと紅葉のライトアップ。帰りの配車と、防寒・足元の明かりを先に用意。'],
 ['11月28日（土） ランタンNight','大師堂で15時受付、17時受渡し、本堂前広場で18時から打ち上げ。1基3,500円・現金のみ。1基につき乳幼児を含む3人まで入場、1人での複数購入・代理購入は不可。'],
 ['11月28・29日 10～14時30分','紫雲閣のお抹茶はLO14時。和菓子付き600円、椅子の立礼席。飲食の休憩候補に。']])+refs('momiji')+
 item('乳幼児と昼に楽しむ提案',journey('配車で門前へ → スタンプラリーと紅葉 → 開催日なら昼のマーケット → だんごなどを持ち帰り → 予約した帰路へ')+'昼の催しは15時までのものが多いため、夜のライトアップを待ち続ける計画にしなくても楽しめます。ランタンは4人家族全員が1基で入場できる条件ではありません。購入・入場の組合せは主催者に確認してください。'))+
 sec('access','車なしなら、三山を一日に詰め込まない',
 item('可睡齋：袋井駅から路線バス＋徒歩','所在地は袋井市久能2915-1。公式案内はJR袋井駅北口1番のりばから遠州森町行き・気多行きに乗り、「可睡斎入口」で下車。<strong>約12分はバス乗車時間の目安</strong>で、境内までの全所要時間ではありません。停留所からの歩行・拝観・門前休憩も加えます。秋葉バスの当日のダイヤで帰りの便を先に決めてください。','kasuibus busouting buslive')+
 item('法多山：JR愛野駅＋配車、歩く場合は道の条件も','所在地は袋井市豊沢2777。袋井駅との旧定期路線バスは2019年3月末に終了しています。法多山は愛野駅から徒歩30～40分の経路を紹介していますが、一部に歩道のない箇所があるため、幼児連れや夜間は配車を組み合わせる計画をおすすめします。駅からの所要時間とは別に境内を歩く時間も必要です。','hattabus')+
 p('法多山の公式案内では、愛野駅にタクシーは常駐していません。行きだけでなく帰りの迎車場所・時間も相談を。掲載窓口は遠鉄タクシー '+a('0538-42-2251','tel:0538422251')+'、袋井タクシー '+a('0538-42-2131','tel:0538422131')+'です。祭典時は乗降規制や予約状況を各社へ確認してください。')+
 item('油山寺：袋井駅＋タクシーを軸に','所在地は袋井市村松1。寺の公式アクセスはJR袋井駅から車で約10分です。これは徒歩や路線バスの所要時間ではありません。ここでは駅からの配車と帰りの予約を組み合わせる計画を案内します。三山を結ぶ常設の周遊バスが使える前提は置きません。','yusan')+
 item('ベビーカー・授乳の確認','法多山FAQは、舗装参道をベビーカーで進め、階段の右側にアスファルトの迂回路があると案内しています。ただし平坦・段差ゼロを保証する説明ではありません。可睡齋の屋内拝観や油山寺の山内散策も、必要な経路と設備を各寺へ確認してください。今回の資料だけでは三山すべての授乳室・おむつ替え台の常設状況は確認できていません。','hattafaq hattamap')+
 p('問い合わせ：法多山 '+a('0538-43-3601','tel:0538433601')+' ／ 可睡齋 '+a('0538-42-2121','tel:0538422121')+' ／ 油山寺 '+a('0538-42-3633','tel:0538423633')+'。'))+
 sec('autumn','秋：紅葉の色づきと、夜の開催日を分ける',
 item('2026年11月時点の色づき','油山寺の11月17日発表では、薬師堂・参道・宝生殿・山門前は色づき始め、瀧堂・放生池は緑。法多山の紅葉情報は11月18日の確認時に、もみじ・いちょうとも一部見頃の表示でした。三山すべてが見頃とは言えず、出発日には更新を確認します。','yusancolor hattacolor')+
 item('可睡齋の紅葉','寺の季節案内は11月下旬～12月上旬を目安にしています。日中の参拝・諸堂拝観と組み合わせ、一般拝観は8時～16時30分、拝観料700円の案内を確認。紅葉の時期だけを根拠に、夜間ライトアップがあるとは案内しません。','kasuimomiji kasuihaikan')+
 item('法多山の秋の行事','年間案内には9月下旬～10月上旬の新月の週末の「星満夜」、11月7日の奥之院大祭があります。次回の実施日・入場条件は年の付いた新着で確認。もみじまつり以外の夜間公開へ、同じ日時を当てはめないでください。','hattayear'))+
 sec('spring','春：ひな飾り、桜、ぼたんをゆっくり',
 item('可睡齋ひなまつり：2026年の開催記録','2026年は1月1日～3月31日、8～17時、700円・小学生以下無料と案内されました。瑞龍閣の32段・約1,200体のひな飾りが見どころです。<strong>2027年の日程・料金は未確認</strong>。屋内で見られる行事ですが、ベビーカーのまま全館を通れるとは限らないため利用経路を事前に相談してください。','kasuihina')+
 item('法多山の桜・さくらまつり','例年の桜は3月下旬～4月上旬。公式の年間案内は3月最終土日・4月第1土日を催しの目安とし、親子写生大会や春のお茶まつりを紹介しています。これは次回の募集要項ではありません。子どもの参加を考えるなら対象・申込・画材・雨天時の扱いを当年の発表で確認します。','hattasakura hattayear')+
 item('可睡齋ぼたん苑','屋外のぼたんは例年4月中旬～5月上旬。寺は約150種・2,000株の苑を紹介しています。年の記載がない一般案内の開苑時間は8～17時、500円・小学生以下無料。当年の開花と開苑期間を確認し、ひなまつり期間の室内ぼたん庭園とは分けて計画します。','kasuibotan')+
 item('油山寺 弘法大師大祭','年間案内では4月21日、11時受付・12時祈祷、2,000円（たけのこご飯付き）、事前予約が必要です。次回の受付状況や子どもの参加条件・食事を寺へ相談し、当日飛び込みの食事イベントとしては案内しません。','yusan'))+
 sec('summer','初夏・夏：風鈴は昼、ホタルや灯りは帰路を先に',
 item('遠州三山 風鈴まつり','2026年の開催期間は5月23日～8月23日で、掲載期間は終了しています。2027年の日程は未確認。法多山の願掛け風鈴、可睡齋の風鈴が並ぶ参道、油山寺の鉄風鈴と、音や飾り方の違いを楽しめる催しです。期間限定の氷・絵付け・飲食サービスは、翌年も同じ料金や日にあると見込まず当年の案内へ。','furin')+
 item('法多山のホタル・あじさい・万灯祭','例年5月下旬頃からのホタルは天候で時期が変わる夜の観賞。あじさいは6月中旬～下旬を目安に昼の散策へ。7月9・10日の万灯祭は灯籠を奉納する行事で、次回の点灯や出店時間は未確認です。夜は帰りの配車を確保し、ホタルには強い照明・フラッシュを向けない配慮を。','hattayear')+
 item('油山寺 百万遍','年間案内は8月8日10時30分、無料で参加できる行事。大数珠を参拝者が囲んで繰ります。次回の開催と参加方法は寺へ確認し、小さな子と一緒の場合は進行に合わせて見学できる位置を相談します。','yusan')+
 item('可睡齋 奥之院不動尊大祭','例年8月28日。公式案内は大祈祷に加え、奉納花火・手筒花火・灯籠流しを紹介しています。次回のプログラムや観覧区画は当年発表を確認。火や花火に近づく観覧を勧めず、係員の指定場所から見る計画に。夜まで見て路線バスで帰れるとは限りません。','kasuifudo'))+
 sec('winter','冬：火まつり、初詣、祈願の行事',
 item('可睡齋 秋葉の火まつり','年の記載がない公式案内は12月15～16日。15日15時の大祈祷から、松明道中などを経て深夜の儀式へ続き、翌朝までの行事です。2026年の変更・参加受付は寺へ確認してください。乳幼児と行く場合は日中の参拝・祈祷を軸にし、深夜までの滞在や火渡りを家族の必須体験にしない計画が組めます。','kasuifire')+
 item('法多山 初詣・田遊祭・節分祭','年間案内には大晦日からの除夜祭、1月の初詣、1月7日の田遊祭、2月の節分祭と2月15～17日の星祭があります。節分の日付や新年の交通規制・臨時輸送は、その年の告知を確認。夜中の参拝だけでなく、子どもの起きていられる日中を選ぶ方法もあります。','hattayear')+
 item('油山寺 星祭中日大祭','例年1月の成人の日に行われ、公式の一般案内は11時受付・12時祈祷、1人2,000円（弁当付き）、事前予約制です。次回の申込可否と子どもの参加・食事条件は寺へ確認。予約不要の自由散策とは分けて計画します。','yusan'))+
 sec('courses','季節の参拝に、食事や休憩を組み合わせる',
 item('路線バスで可睡齋を訪ねる日',journey('袋井駅北口 → 可睡斎入口 → 花・ひな飾り・紅葉のうち開催中のもの → 門前の休憩 → 帰りのバス')+'帰りの便を決めてから到着便を選びます。食べ歩きを加えるなら'+a('メロン・門前のジェラート・買い物ガイド',B+'melon-markets/')+'へ。曜日によって休業する店や数量限定品もあります。')+
 item('法多山の灯りを見に行く日',journey('事前に往復配車を相談 → 日没前に門前へ → 参拝・指定日のライトアップ → 予約した乗車場所へ')+'行事の終了時刻を、そのまま門前で乗れる時刻にしないよう、境内を戻る時間を見込みます。雨天変更が出たときは、交通の予約変更も合わせて確認します。')+
 item('油山寺を日中に訪ねる日','配車で往復を決め、山門や参道の紅葉を子どもの歩ける範囲で。屋内の方丈・宝生殿・書院の拝観は9～16時30分、300円・高校生以下無料の案内です。法話は10人以上の団体で事前予約が必要なため、親子でいつでも受けられる常設プログラムとしては案内しません。','yusanvisit')))

